// WantsBlink reports whether an Images row is in an animated state (running,
// or an action observed on it). A queued row and a remembered failure are
// steady. It is the level the router's BlinkingView check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	return false
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		return m, nil

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Tab / Shift+Tab cycles between the three tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
		initCmd = view.Init()
	}
	log.Printf("Views reinitialized successfully")
	return initCmd
}

// BlinkingView is implemented by a view with a row that blinks for a reason the
// registry does not know (an instant action, an agent running, children loading).
// The router asks the view on screen after every Update: a level, not an edge.
type BlinkingView interface {
	WantsBlink() bool
}

// Update is the router's only entry: the dispatch, then the level check of the
// animation chain. The view's own Cmd goes through untouched; ensureTick adds a
// Cmd only when a chain has to start or be replaced, and is idempotent, so a
// handler that already called it (jobsChanged) does not double the interval.
func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	model, cmd := a.update(msg)
	return model, tea.Batch(cmd, a.ensureTick())
}

// wantsBlink reports whether the view on screen has a row that blinks.
func (a *App) wantsBlink() bool {
	view, ok := a.views[a.currentView].(BlinkingView)
	return ok && view.WantsBlink()
}

// applyMotion points the animation at the motion a config asks for. It is
// called wherever the router takes a new config (context switch, every save);
// the constructor sets the field directly because it has no Cmd to return.

